const rect = penpot.createRectangle();
rect.resize(150, 150);
rect.fills = [{ fillColor: '#FF0000', fillOpacity: 1 }];
const center = penpot.viewport.center;
rect.x = center.x;
rect.y = center.y;

const rect = penpot.createRectangle();
rect.resize(200, 150);
rect.name = 'Rectangle stylisé';
rect.fills = [{ fillColor: '#7EFFF5', fillOpacity: 1 }];
rect.borderRadius = 8;
rect.strokes = [{
  strokeColor: '#2e3434',
  strokeStyle: 'solid',
  strokeWidth: 2,
  strokeAlignment: 'center'
}];

const text = penpot.createText('Hello World!');
text.fontSize = '24';
text.fontWeight = '700';
text.textTransform = 'uppercase';
text.fills = [{ fillColor: '#FF6FE0', fillOpacity: 1 }];
const center = penpot.viewport.center;
text.x = center.x;
text.y = center.y;

const text = penpot.createText('Hello World!');
text.fontSize = '20';
const range = text.getRange(0, 5);
range.fontSize = '40';
range.fills = [{ fillColor: '#ff6fe0', fillOpacity: 1 }];
text.x = penpot.viewport.center.x;
text.y = penpot.viewport.center.y;

for (let i = 0; i < 3; i++) {
  const rect = penpot.createRectangle();
  rect.resize(200, 150);
  rect.x = 100 + i * 250;
  rect.y = 100;
  rect.fills = [{ fillColor: `hsl(${i * 120}, 70%, 50%)`, fillOpacity: 1 }];
}

const circle = penpot.createEllipse();
circle.resize(100, 100);
circle.fills = [{ fillColor: '#0000FF', fillOpacity: 1 }];
circle.x = penpot.viewport.center.x;
circle.y = penpot.viewport.center.y;

const rect1 = penpot.createRectangle();
rect1.resize(100, 100);
rect1.x = 100;
rect1.y = 100;

const rect2 = penpot.createRectangle();
rect2.resize(100, 100);
rect2.x = 250;
rect2.y = 100;

penpot.group([rect1, rect2]);

const board = penpot.createBoard();
board.horizontalSizing = 'auto';
board.verticalSizing = 'auto';

const flex = board.addFlexLayout();
flex.dir = 'column';
flex.alignItems = 'center';
flex.justifyContent = 'center';
flex.verticalPadding = 10;
flex.horizontalPadding = 10;

board.appendChild(penpot.createRectangle());
board.appendChild(penpot.createEllipse());

const colors = ['#0055A4', '#FFFFFF', '#EF4135'];
for (let i = 0; i < 3; i++) {
  const stripe = penpot.createRectangle();
  stripe.resize(100, 200);
  stripe.x = 100 + i * 100;
  stripe.y = 100;
  stripe.fills = [{ fillColor: colors[i], fillOpacity: 1 }];
  stripe.name = `Stripe ${i + 1}`;
}

const card = penpot.createBoard();
card.resize(300, 400);
card.fills = [{ fillColor: '#FFFFFF', fillOpacity: 1 }];
card.strokes = [{ strokeColor: '#E0E0E0', strokeWidth: 1, strokeStyle: 'solid' }];
card.borderRadius = 8;

const title = penpot.createText('Titre de la carte');
title.fontSize = '24';
title.fontWeight = '700';
title.x = card.x + 20;
title.y = card.y + 20;

const content = penpot.createText('Contenu de la carte avec plus de détails...');
content.fontSize = '16';
content.x = card.x + 20;
content.y = card.y + 80;

card.appendChild(title);
card.appendChild(content);
